import React, { useState } from "react";
import "./BudgetLimits.css";

function BudgetLimits({
  incomeCategory,
  questionnaire,
  spendingPriorities = {},
  onSave
}) {
  // ✅ Filter only categories with priority >= 3
  const activeCategories = Object.keys(spendingPriorities || {}).filter(
    (cat) => Number(spendingPriorities[cat]) >= 3
  );

  // ✅ Create local state for inputs
  const [limits, setLimits] = useState({});

  const handleChange = (category, value) => {
    setLimits((prev) => ({
      ...prev,
      [category]: value
    }));
  };

  const handleSubmit = async () => {
    const finalData = {
      incomeCategory,
      questionnaire,
      spendingPriorities,
      budgetLimits: limits
    };

    try {
      const response = await fetch("http://localhost:5000/save-budget", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify(finalData)
      });

      const data = await response.json();

      if (response.ok) {
        alert("Data saved successfully!");
        if (onSave) onSave(finalData);
      } else {
        alert(data.error || "Save failed");
      }
    } catch (error) {
      console.error(error);
      alert("Server connection failed");
    }
  };

  return (
    <div className="budget-container">
      <div className="budget-card">
        <h2 className="budget-title">Set Monthly Budget Limits</h2>

        {activeCategories.length === 0 ? (
          <p style={{ textAlign: "center", marginTop: "20px" }}>
            No categories selected for budgeting
          </p>
        ) : (
          activeCategories.map((category) => (
            <div key={category} className="form-group">
              <label className="form-label">{category}</label>
              <input
                type="number"
                className="form-input"
                placeholder="Enter amount"
                value={limits[category] || ""}
                onChange={(e) =>
                  handleChange(category, e.target.value)
                }
              />
            </div>
          ))
        )}

        <button className="next-button" onClick={handleSubmit}>
          Save Budget
        </button>
      </div>
    </div>
  );
}

export default BudgetLimits;
